export const EVENT_REGISTRY_RATIFIABLE = true as const;

const registrationsByIdentity = new Map(
  EVENT_REGISTRATIONS.map((entry) => [`${entry.fullName}\u0000${entry.version}`, entry]),
);

export function requireEventRegistration(
  fullName: string,
  version: number,
  contentType: string,
): EventRegistration {
  const registration = registrationsByIdentity.get(`${fullName}\u0000${version}`);
  if (registration === undefined) {
    throw new Error(`unregistered event type/version: ${fullName}@${version}`);
  }
  if (registration.contentType !== contentType) {
    throw new Error(
      `event content type mismatch: expected ${registration.contentType}, got ${contentType}`,
    );
  }
  return registration;
}
